UPDATE pnn_content SET introtext = '<p class="roster-lead">Kepaniteraan Pidana Pengadilan Negeri Natuna melaksanakan administrasi perkara pidana pada tingkat pertama sesuai ketentuan hukum acara dan pedoman administrasi perkara yang berlaku.</p><section class="roster-section"><div class="roster-section-head"><h2>Penanggung Jawab</h2></div><div class="roster-grid"><article class="roster-card"><div class="roster-photo"><img src="/images/profil/pegawai/kepaniteraan/ari.png" alt="Ari Putra Utama, A.Md. A.B." loading="lazy"><span class="roster-degree">D3</span></div><div class="roster-body"><h3 class="roster-name">Ari Putra Utama, A.Md. A.B.</h3><div class="roster-role-row"><span class="roster-role">Plt. Panitera Muda Pidana</span><span class="roster-role">Panitera Pengganti</span></div><dl class="roster-meta"><div><dt>NIP</dt><dd>199811252022031008</dd></div><div><dt>Pangkat/Gol.</dt><dd>Pengatur / II.c</dd></div></dl></div></article></div></section><section class="roster-section"><div class="roster-section-head"><h2>Ruang Lingkup Layanan</h2></div><ul class="unit-scope"><li>Administrasi penerimaan, pencatatan, dan pengelolaan perkara pidana.</li><li>Pelayanan informasi perkara pidana melalui PTSP dan sistem resmi yang berlaku.</li><li>Dukungan administrasi persidangan dan penyelesaian perkara pidana.</li></ul></section><section class="roster-section"><div class="roster-section-head"><h2>Alur Perkara Pidana</h2></div><button type="button" class="maklumat-doc alur-frame" data-maklumat-zoom="/images/layanan/alur/alur-pidana-biasa.png" data-maklumat-label="Alur Perkara Pidana Biasa Pengadilan Negeri Natuna" aria-label="Perbesar bagan alur perkara pidana"><img src="/images/layanan/alur/alur-pidana-biasa.png" alt="Alur perkara pidana biasa di Pengadilan Negeri Natuna" loading="lazy"><span class="maklumat-zoom-hint" aria-hidden="true"><svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><circle cx="11" cy="11" r="7"></circle><path d="m21 21-4.3-4.3"></path><path d="M11 8v6M8 11h6"></path></svg>Klik untuk perbesar</span></button></section><section class="roster-section"><div class="roster-section-head"><h2>Alur Diversi</h2></div><button type="button" class="maklumat-doc alur-frame" data-maklumat-zoom="/images/layanan/alur/alur-pelaksanaan-diversi.png" data-maklumat-label="Alur Pelaksanaan Diversi Perkara Anak" aria-label="Perbesar bagan alur pelaksanaan diversi"><img src="/images/layanan/alur/alur-pelaksanaan-diversi.png" alt="Alur pelaksanaan diversi perkara anak" loading="lazy"><span class="maklumat-zoom-hint" aria-hidden="true"><svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><circle cx="11" cy="11" r="7"></circle><path d="m21 21-4.3-4.3"></path><path d="M11 8v6M8 11h6"></path></svg>Klik untuk perbesar</span></button></section><p class="content-note">Informasi teknis dapat ditanyakan melalui PTSP Pengadilan Negeri Natuna atau kanal resmi yang tersedia.</p>' WHERE id = 107;

UPDATE pnn_content SET introtext = '<p class="roster-lead">Kepaniteraan Perdata Pengadilan Negeri Natuna melaksanakan administrasi perkara perdata, permohonan, gugatan, dan layanan terkait perkara perdata sesuai ketentuan yang berlaku.</p><section class="roster-section"><div class="roster-section-head"><h2>Penanggung Jawab</h2></div><div class="roster-grid"><article class="roster-card"><div class="roster-photo"><img src="/images/profil/pegawai/kepaniteraan/hadry.jpg" alt="Hadry B., S.H." loading="lazy"><span class="roster-degree">S1</span></div><div class="roster-body"><h3 class="roster-name">Hadry B., S.H.</h3><div class="roster-role-row"><span class="roster-role">Plt. Panitera Muda Perdata</span><span class="roster-role">Panitera</span></div><dl class="roster-meta"><div><dt>NIP</dt><dd>197809302011011005</dd></div><div><dt>Pangkat/Gol.</dt><dd>Penata Tingkat I / III.d</dd></div></dl></div></article></div></section><section class="roster-section"><div class="roster-section-head"><h2>Ruang Lingkup Layanan</h2></div><ul class="unit-scope"><li>Administrasi penerimaan dan pengelolaan perkara perdata.</li><li>Pelayanan informasi perkara perdata melalui PTSP dan sistem resmi yang berlaku.</li><li>Dukungan administrasi persidangan, mediasi, dan penyelesaian perkara perdata.</li></ul></section><section class="roster-section"><div class="roster-section-head"><h2>Alur Perkara Perdata</h2></div><button type="button" class="maklumat-doc alur-frame" data-maklumat-zoom="/images/layanan/alur/alur-perkara-perdata.jpg" data-maklumat-label="Alur Perkara Perdata Pengadilan Negeri Natuna" aria-label="Perbesar bagan alur perkara perdata"><img src="/images/layanan/alur/alur-perkara-perdata.jpg" alt="Alur perkara perdata di Pengadilan Negeri Natuna" loading="lazy"><span class="maklumat-zoom-hint" aria-hidden="true"><svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><circle cx="11" cy="11" r="7"></circle><path d="m21 21-4.3-4.3"></path><path d="M11 8v6M8 11h6"></path></svg>Klik untuk perbesar</span></button></section><p class="content-note">Informasi teknis dapat ditanyakan melalui PTSP Pengadilan Negeri Natuna atau kanal resmi yang tersedia.</p>' WHERE id = 108;

UPDATE pnn_content SET introtext = '<p class="roster-lead">Kepaniteraan Hukum Pengadilan Negeri Natuna melaksanakan layanan administrasi hukum, informasi, arsip, dan layanan permohonan tertentu sesuai kewenangan pengadilan negeri.</p><section class="roster-section"><div class="roster-section-head"><h2>Penanggung Jawab</h2></div><div class="roster-grid"><article class="roster-card"><div class="roster-photo"><img src="/images/profil/pegawai/kepaniteraan/jhivo.png" alt="Jhivo Wilanda, S.H." loading="lazy"><span class="roster-degree">S1</span></div><div class="roster-body"><h3 class="roster-name">Jhivo Wilanda, S.H.</h3><div class="roster-role-row"><span class="roster-role">Plt. Panitera Muda Hukum</span><span class="roster-role">Panitera Pengganti</span></div><dl class="roster-meta"><div><dt>NIP</dt><dd>199604232020121001</dd></div><div><dt>Pangkat/Gol.</dt><dd>Penata Muda Tk. I / III.b</dd></div></dl></div></article></div></section><section class="roster-section"><div class="roster-section-head"><h2>Layanan Permohonan</h2></div><ul class="unit-scope unit-scope-2"><li>Permohonan surat keterangan tidak pernah dipidana.</li><li>Permohonan surat keterangan tidak sedang dicabut hak pilihnya.</li><li>Pendaftaran surat kuasa dan surat kuasa insidentil.</li><li>Legalisasi atau layanan administrasi hukum lain sesuai ketentuan.</li></ul></section><section class="roster-section"><div class="roster-section-head"><h2>Catatan Persyaratan</h2></div><p>Persyaratan dokumen dapat meliputi surat permohonan bermeterai, identitas pemohon, dokumen pendukung, pasfoto, salinan dokumen terkait, dan map layanan sesuai jenis permohonan. Persyaratan rinci dapat dikonfirmasi melalui PTSP agar sesuai ketentuan terbaru.</p></section><p class="content-note">Informasi teknis dapat ditanyakan melalui PTSP atau Kepaniteraan Hukum Pengadilan Negeri Natuna.</p>' WHERE id = 109;

UPDATE pnn_content SET introtext = '<p class="roster-lead">Kepaniteraan Khusus Perikanan Pengadilan Negeri Natuna melaksanakan administrasi perkara tindak pidana perikanan sesuai kewenangan pengadilan dan ketentuan hukum acara yang berlaku.</p><section class="roster-section"><div class="roster-section-head"><h2>Penanggung Jawab</h2></div><div class="roster-grid"><article class="roster-card"><div class="roster-photo"><img src="/images/profil/pegawai/kepaniteraan/hadry.jpg" alt="Hadry B., S.H." loading="lazy"><span class="roster-degree">S1</span></div><div class="roster-body"><h3 class="roster-name">Hadry B., S.H.</h3><div class="roster-role-row"><span class="roster-role">Plt. Panitera Muda Khusus Perikanan</span><span class="roster-role">Panitera</span></div><dl class="roster-meta"><div><dt>NIP</dt><dd>197809302011011005</dd></div><div><dt>Pangkat/Gol.</dt><dd>Penata Tingkat I / III.d</dd></div></dl></div></article></div></section><section class="roster-section"><div class="roster-section-head"><h2>Ruang Lingkup Layanan</h2></div><ul class="unit-scope"><li>Administrasi penerimaan dan pencatatan perkara perikanan.</li><li>Pelayanan informasi perkara melalui PTSP dan sistem resmi yang berlaku.</li><li>Dukungan administrasi persidangan dan penyelesaian perkara perikanan.</li></ul></section><section class="roster-section"><div class="roster-section-head"><h2>Alur Perkara Perikanan</h2></div><button type="button" class="maklumat-doc alur-frame" data-maklumat-zoom="/images/layanan/alur/alur-perkara-perikanan.jpg" data-maklumat-label="Alur Perkara Perikanan Pengadilan Negeri Natuna" aria-label="Perbesar bagan alur perkara perikanan"><img src="/images/layanan/alur/alur-perkara-perikanan.jpg" alt="Alur perkara perikanan di Pengadilan Negeri Natuna" loading="lazy"><span class="maklumat-zoom-hint" aria-hidden="true"><svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><circle cx="11" cy="11" r="7"></circle><path d="m21 21-4.3-4.3"></path><path d="M11 8v6M8 11h6"></path></svg>Klik untuk perbesar</span></button></section><p class="content-note">Informasi teknis dapat ditanyakan melalui PTSP Pengadilan Negeri Natuna atau kanal resmi yang tersedia.</p>' WHERE id = 110;
